function I({registerIndicator:S,sourceValues:v,nulls:Q}){S({id:"oa-nyqma",name:"Nyquist Moving Average (NYQMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period (N1)",default:89,min:3,max:5e3,step:1},{key:"nyquistPeriod",type:"number",label:"Nyquist Period (N2)",default:21,min:1,max:5e3,step:1,tooltip:"Secondary weighted-average period, clamped to at most half of Period (N1)."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"nyqma",type:"line",title:"NYQMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(u,d){const t=Math.max(3,Math.floor(Number(d.period)||89)),Y=Math.max(1,Math.floor(Number(d.nyquistPeriod)||21)),p=v(u,d.source||"close"),o=Math.min(Math.max(Y,1),Math.floor(t/2)),h=o/(t-o),b=new Array(t).fill(NaN);let r=0,s=0,n=0,N=0;const M=new Array(o).fill(NaN);let c=0,m=0,i=0,y=0;const q=new Array(u.length).fill(NaN);for(let a=0;a<u.length;a++){const l=Number.isFinite(p[a])?p[a]:0,w=b[r];if(Number.isFinite(w)){const f=s;s=s-w+l,n=n-f+t*l}else N+=1,s+=l,n=n+N*l;b[r]=l,r=(r+1)%t;const x=Math.min(N,t),A=x*(x+1)*.5,e=A>0?n/A:NaN;if(!Number.isFinite(e))continue;const F=M[c];if(Number.isFinite(F)){const f=m;m=m-F+e,i=i-f+o*e}else y+=1,m+=e,i=i+y*e;M[c]=e,c=(c+1)%o;const P=Math.min(y,o),g=P*(P+1)*.5,k=g>0?i/g:NaN;Number.isFinite(k)&&(q[a]=(1+h)*e-h*k)}return{nyqma:Q(q)}}})}export{I as default};
